// "5MB" | "512KB" | 1024 -> bytes
export function parseSize(size) {
    if (typeof size === 'number')
        return size;
    const m = /^(\d+(?:\.\d+)?)\s*(B|KB|MB|GB)?$/i.exec(size.trim());
    if (!m)
        throw new Error(`Invalid size: ${size}`);
    const n = Number(m[1]);
    const unit = (m[2] ?? 'B').toUpperCase();
    const mult = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 }[unit] ?? 1;
    return Math.round(n * mult);
}
export class ColumnBuilder {
    ir;
    constructor(ir) {
        this.ir = ir;
    }
    // What an agent reads when deciding what to put here.
    describe(text) {
        this.ir.description = text;
        return this;
    }
    primaryKey() {
        this.ir.primaryKey = true;
        this.ir.notNull = true;
        return this;
    }
    notNull() {
        this.ir.notNull = true;
        return this;
    }
    unique() {
        this.ir.unique = true;
        return this;
    }
    default(value) {
        this.ir.default = value;
        return this;
    }
    references(target) {
        this.ir.references = target;
        return this;
    }
}
export class TableBuilder {
    columns = [];
    indexes = [];
    _description;
    _agentVisible;
    describe(text) {
        this._description = text;
        return this;
    }
    // Keep this table out of the app's generated agent tool surface. Curation,
    // not access control — see the TableIR comment.
    agentVisible(visible) {
        this._agentVisible = visible;
        return this;
    }
    col(name, type) {
        const ir = { name, type };
        this.columns.push(ir);
        return new ColumnBuilder(ir);
    }
    text(name) { return this.col(name, 'text'); }
    uuid(name) { return this.col(name, 'uuid'); }
    integer(name) { return this.col(name, 'integer'); }
    bigint(name) { return this.col(name, 'bigint'); }
    boolean(name) { return this.col(name, 'boolean'); }
    jsonb(name) { return this.col(name, 'jsonb'); }
    timestamp(name) { return this.col(name, 'timestamp'); }
    timestamps() {
        this.col('createdAt', 'timestamp').notNull();
        this.col('updatedAt', 'timestamp').notNull();
        return this;
    }
    index(columns, options = {}) {
        this.indexes.push({ columns, ...(options.unique ? { unique: true } : {}) });
        return this;
    }
    build(name) {
        return {
            name,
            columns: this.columns,
            indexes: this.indexes,
            ...(this._description !== undefined ? { description: this._description } : {}),
            ...(this._agentVisible !== undefined ? { agentVisible: this._agentVisible } : {}),
        };
    }
}
// A resource-owned table also carries access rules.
export class ResourceTableBuilder extends TableBuilder {
    accessRules = {};
    access(rules) {
        this.accessRules = rules;
        return this;
    }
    buildResourceTable(name) {
        return { ...this.build(name), access: this.accessRules };
    }
}
export class BucketBuilder {
    _maxFileSizeBytes;
    _accept;
    maxFileSize(size) {
        this._maxFileSizeBytes = parseSize(size);
        return this;
    }
    accept(mimeTypes) {
        this._accept = mimeTypes;
        return this;
    }
    build(name) {
        return {
            name,
            ...(this._maxFileSizeBytes !== undefined ? { maxFileSizeBytes: this._maxFileSizeBytes } : {}),
            ...(this._accept ? { accept: this._accept } : {}),
        };
    }
}
export class ResourceFilesBuilder extends BucketBuilder {
    accessRules = {};
    access(rules) {
        this.accessRules = rules;
        return this;
    }
    buildResourceFiles(name) {
        return { ...this.build(name), access: this.accessRules };
    }
}
export class MountBuilder {
    _onMemberRemove = 'remove';
    _onOwnerDelete = 'remove';
    accessRules = {};
    onMemberRemove(action) {
        this._onMemberRemove = action;
        return this;
    }
    onOwnerDelete(action) {
        this._onOwnerDelete = action;
        return this;
    }
    access(rules) {
        this.accessRules = rules;
        return this;
    }
    build(table) {
        return {
            table,
            onMemberRemove: this._onMemberRemove,
            onOwnerDelete: this._onOwnerDelete,
            access: this.accessRules,
        };
    }
}
export class ChannelBuilder {
    _subscribe;
    _publish;
    subscribe(role) {
        this._subscribe = role;
        return this;
    }
    publish(role) {
        this._publish = role;
        return this;
    }
    build(name) {
        return {
            name,
            ...(this._subscribe ? { subscribe: this._subscribe } : {}),
            ...(this._publish ? { publish: this._publish } : {}),
        };
    }
}
export class PresenceBuilder {
    _read;
    read(role) {
        this._read = role;
        return this;
    }
    build() {
        return { ...(this._read ? { read: this._read } : {}) };
    }
}
export class ResourceBuilder {
    _description;
    _agentVisible;
    _visibility = 'members';
    _visibilityChoices;
    _payer = 'actor';
    _defaultRole = 'reader';
    _grant;
    _discoverable = false;
    _visitors = { read: false };
    _statics = [];
    _mounts = [];
    _tables = [];
    _files = [];
    _channels = [];
    _presence;
    // One enum covers the three meaningful states — a members-only resource
    // can't be discoverable, so separate flags would allow an impossible combo.
    // The object form opts instances into choosing their own state at create
    // time; the type's declaration then acts as default + bound, not constant.
    visibility(v) {
        const def = typeof v === 'string' ? v : v.default;
        this._visibility = def === 'members' ? 'members' : 'public';
        this._discoverable = def === 'discoverable';
        this._visibilityChoices = typeof v === 'string' ? undefined : [...new Set([def, ...v.allow])];
        return this;
    }
    describe(text) {
        this._description = text;
        return this;
    }
    // Hides this resource type and every table under it from the agent surface.
    agentVisible(visible) {
        this._agentVisible = visible;
        return this;
    }
    payer(p) {
        this._payer = p;
        return this;
    }
    defaultRole(r) {
        this._defaultRole = r;
        return this;
    }
    grant(g) {
        this._grant = g;
        return this;
    }
    visitors(v) {
        this._visitors = v;
        return this;
    }
    static(slugs) {
        this._statics = slugs;
        return this;
    }
    // Publish a top-level creator-owned table into this resource type. Rows stay
    // owned by their creators; the resource is a context they appear in.
    shares(table, cb) {
        const b = new MountBuilder();
        cb(b);
        this._mounts.push(b.build(table));
        return this;
    }
    // Declare a table owned by the resource entity itself: rows belong to the
    // resource, die with it, and bill per its payer policy.
    owns(name, cb) {
        const b = new ResourceTableBuilder();
        cb(b);
        this._tables.push(b.buildResourceTable(name));
        return this;
    }
    files(name, cb) {
        const b = new ResourceFilesBuilder();
        cb(b);
        this._files.push(b.buildResourceFiles(name));
        return this;
    }
    channel(name, cb) {
        const b = new ChannelBuilder();
        cb(b);
        this._channels.push(b.build(name));
        return this;
    }
    presence(cb) {
        const b = new PresenceBuilder();
        cb(b);
        this._presence = b.build();
        return this;
    }
    build(type) {
        return {
            type,
            ...(this._description !== undefined ? { description: this._description } : {}),
            ...(this._agentVisible !== undefined ? { agentVisible: this._agentVisible } : {}),
            visibility: this._visibility,
            ...(this._visibilityChoices ? { visibilityChoices: this._visibilityChoices } : {}),
            payer: this._payer,
            defaultRole: this._defaultRole,
            ...(this._grant ? { grant: this._grant } : {}),
            discoverable: this._discoverable,
            visitors: this._visitors,
            statics: this._statics,
            mounts: this._mounts,
            tables: this._tables,
            files: this._files,
            channels: this._channels,
            ...(this._presence ? { presence: this._presence } : {}),
        };
    }
}
